//! Cube-and-conquer driver: cubes (consistent partial boards) are generated by the rowscan_dfs
//! row-scan split phase; each cube is solved by the SAT solver with those edges fixed.
//! External cube IO: --cubes-file FILE, --dump-cubes FILE, --cube-stats FILE.
//! usage: numlin_sat_cube [--rules off|diag|wedge|g2|diag,wedge,g2] [--full-cover] [--short-only] [--log-encoding] [--threads N] [--cubes M] [--transform K] [--max A] [--cube-rules strong|off (default strong)] [--cube-order default|big-first] [--assumptions] [--share-every K] [--budget CONFLICTS] [--resplit N] [--balance SLACK] [--balance-mean N] [--balance-verify F] [--verify-min M] [--verify-floor N] [--probes P] [--est-study P1,P2,...] [--est-only] [--score K] [--score-factor F (10)] [--score-min-total T (1e8)] [--score-rounds R (3)] [--no-steal] [--steal-min SECS (default 20)] [--parent-cutoff F (default 1, 0 = off)] [--overrun FACTOR (default 0 = off)] [--overrun-min SECS (default 60)] [--exact-count] [--fresh-assumptions] [--fixed-units] [--share-pool] [--share-max-size N] [--share-max-lbd N] [--check-shared] [--edges-only] [--rnd-freq F] [--reduce-db FIRST,INC] [--verify-cubes] URL
use cspuz_rs_puzzles::puzzles::numlin::{
    enumerate_answers_numlin_with_options, FixedEdge, InterruptHandle, NumlinAssumptionSolver,
    NumlinOptions, NumlinSatLiteral,
};
use cspuz_solver_backend::cubes::{
    estimate_cube_size, generate_cubes_balanced_verify_floor, split_cube, Cube, SolveOptions,
};
use cspuz_solver_backend::cubes::{Problem, strong_options, balance_cubes, TRANSFORM_NAMES};
use std::collections::HashSet;
use std::collections::VecDeque;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Mutex;
use std::time::Instant;

#[derive(Default)]
struct ClausePool {
    clauses: Vec<(usize, Vec<NumlinSatLiteral>)>,
    seen: HashSet<Vec<NumlinSatLiteral>>,
    fingerprint: Option<u64>,
    learned: u64,
    independent: u64,
    checked: u64,
    eligible: u64,
    imported: u64,
}

impl ClausePool {
    fn assert_encoding(&mut self, solver: &NumlinAssumptionSolver) {
        let fingerprint = solver.encoding_fingerprint();
        if let Some(expected) = self.fingerprint {
            assert_eq!(
                expected, fingerprint,
                "workers have different SAT encodings"
            );
        } else {
            self.fingerprint = Some(fingerprint);
        }
    }

    fn snapshot(&mut self, solver: &NumlinAssumptionSolver) -> Vec<Vec<NumlinSatLiteral>> {
        self.assert_encoding(solver);
        self.imported += self.clauses.len() as u64;
        self.clauses.iter().map(|(_, c)| c.clone()).collect()
    }

    fn publish(
        &mut self,
        worker: usize,
        solver: &NumlinAssumptionSolver,
        mut clauses: Vec<Vec<NumlinSatLiteral>>,
    ) {
        self.assert_encoding(solver);
        self.eligible += clauses.len() as u64;
        clauses.sort_by_key(Vec::len);
        for clause in clauses {
            if self.clauses.len() >= 50_000 {
                break;
            }
            if self.seen.insert(clause.clone()) {
                self.clauses.push((worker, clause));
            }
        }
        self.clauses.sort_by_key(|(_, clause)| clause.len());
    }

    fn exchange(&mut self, worker: usize, solver: &mut NumlinAssumptionSolver, cursor: &mut usize) {
        let fingerprint = solver.encoding_fingerprint();
        if let Some(expected) = self.fingerprint {
            assert_eq!(
                expected, fingerprint,
                "workers have different SAT encodings"
            );
        } else {
            self.fingerprint = Some(fingerprint);
        }
        for (source, clause) in &self.clauses[*cursor..] {
            if *source != worker {
                solver.add_learnt(clause);
            }
        }
        let mut clauses = solver.learnts();
        clauses.sort_by_key(Vec::len);
        for clause in clauses {
            if self.clauses.len() >= 50_000 {
                break;
            }
            if self.seen.insert(clause.clone()) {
                self.clauses.push((worker, clause));
            }
        }
        *cursor = self.clauses.len();
    }
}

use cspuz_rs::solver::Config;

/// Parse external cubes before any SAT work. Never include the input URL in errors or artifacts.
fn read_cubes(
    path: &str,
    w: usize,
    h: usize,
    direction: usize,
) -> Result<(Vec<Cube>, usize), String> {
    let data = std::fs::read_to_string(path).map_err(|e| format!("cube file: {e}"))?;
    let value = json::parse(&data).map_err(|e| format!("cube JSON: {e}"))?;
    if value["width"].as_usize() != Some(w) || value["height"].as_usize() != Some(h) {
        return Err("cube width/height mismatch after transform".into());
    }
    if value["direction"].as_usize() != Some(direction) {
        return Err("cube direction mismatch with --transform".into());
    }
    if !value["cubes"].is_array() {
        return Err("cubes must be an array".into());
    }
    let found = value["solutions_while_splitting"]
        .as_usize()
        .ok_or("invalid solutions_while_splitting")?;
    let mut cubes = Vec::new();
    for c in value["cubes"].members() {
        let next = c["next"]
            .as_usize()
            .filter(|&n| n <= w * h)
            .ok_or("invalid cube next")?;
        let weight = c["weight"]
            .as_f64()
            .filter(|v| v.is_finite() && *v >= 0.0)
            .ok_or("invalid cube weight")?;
        if !c["edges"].is_array() {
            return Err("cube edges must be an array".into());
        }
        let mut edges = Vec::new();
        let mut seen = HashSet::new();
        for e in c["edges"].members() {
            if !e.is_array() || e.len() != 3 {
                return Err("edge must be [y,x,bool]".into());
            }
            let y = e[0].as_usize().ok_or("invalid edge y")?;
            let x = e[1].as_usize().ok_or("invalid edge x")?;
            let line = e[2].as_bool().ok_or("invalid edge value")?;
            if y >= 2 * h - 1 || x >= 2 * w - 1 || y % 2 == x % 2 {
                return Err("invalid edge-grid coordinate".into());
            }
            if !seen.insert((y, x)) {
                return Err("duplicate cube edge".into());
            }
            edges.push((y, x, line));
        }
        // Re-splitting starts at next; an incomplete preceding cell would skip decisions.
        for at in 0..next {
            let (y, x) = (at / w, at % w);
            if (x + 1 < w && !seen.contains(&(2 * y, 2 * x + 1)))
                || (y + 1 < h && !seen.contains(&(2 * y + 1, 2 * x)))
            {
                return Err("undecided edge before cube next".into());
            }
        }
        cubes.push(Cube {
            edges,
            next,
            weight,
        });
    }
    Ok((cubes, found))
}
fn write_cubes(
    path: &str,
    cubes: &[Cube],
    w: usize,
    h: usize,
    direction: usize,
    found: usize,
    elapsed: f64,
) {
    let list: Vec<_> = cubes
        .iter()
        .map(|c| {
            let edges: Vec<_> = c
                .edges
                .iter()
                .map(|&(y, x, v)| json::array![y, x, v])
                .collect();
            json::object! {edges: edges, next: c.next, weight: c.weight}
        })
        .collect();
    let value = json::object! {width:w,height:h,direction:direction,cubes:list,solutions_while_splitting:found,steps:json::Null,elapsed_ms:elapsed*1000.0};
    std::fs::write(path, value.dump() + "\n").expect("write cube dump");
}

#[allow(clippy::too_many_arguments)]
fn balance_external(
    problem: &Problem, cubes: Vec<Cube>, threads: usize, slack: f64, mean_factor: f64,
    verify: f64, verify_min: f64, floor: f64, probes: usize, opts: &SolveOptions,
) -> (Vec<Cube>, usize) {
    balance_cubes(problem, cubes, 0, threads, slack, mean_factor, verify, verify_min, floor, probes, 1 << 15, opts)
}

fn main() {
    let mut args = std::env::args().skip(1);
    let mut rnd_freq: Option<f64> = None;
    let mut reduce_db: Option<(i32, i32)> = None;
    let mut threads = 4usize;
    let mut cubes = 64usize;
    let mut cubes_file: Option<String> = None;
    let mut cube_stats: Option<String> = None;
    let mut dump_cubes: Option<String> = None;
    let mut transform = 0usize;
    let mut max = 2usize;
    let mut url = None;
    // Default rules: wedge only (g34 8 threads: 6:56 -> 6:52 with strong cubes; 9:14 -> 7:35
    // with plain cubes; diag cancels the gain). `--rules off` disables it.
    let mut options = NumlinOptions::default();
    options.rules.wedge = true;
    // Default: split with the strong pruning rule set (stronger propagation gives better cubes;
    // g34 8 threads 9:03 -> 6:56). `--cube-rules off` restores the plain split.
    let mut cube_options = strong_options();
    let mut big_first = false;
    let mut assumptions = false;
    let mut share_every = 8usize;
    let mut verify_cubes = false;
    let mut budget = 0u64;
    let mut resplit = 4usize;
    // Default: estimate-balanced cubes (split any cube above total/(threads*4)); 0 disables.
    let mut balance = 4.0f64;
    // --balance-mean N: split every cube above N x the mean cube (mean recomputed as cubes are
    // added); 0 = use the total/(threads*slack) limit.
    let mut balance_mean = 0.0f64;
    // --balance-verify F [--verify-min M]: split cubes >= M x mean once; if the children's estimates
    // sum to > F x the parent's, the parent was underestimated and the children replace it.
    let mut balance_verify = 0.0f64;
    let mut verify_min = 2.0f64;
    // --verify-floor N: never verify/split cubes estimated below N nodes (absolute).
    let mut verify_floor = 0.0f64;
    let mut steal = true;
    // --steal-min SECS: only steal from a cube that has run at least this long (2026-11-04: in the
    // pp26 tail, idle workers split cubes that had run 0.1-3 s, paying ~0.5 s of build per part).
    let mut steal_min = 20.0f64;
    // --parent-cutoff F (default 1 = on; 0 = off): after a steal the parent keeps running, but once
    // the busy time its children have accumulated exceeds F x the parent's own running time, the
    // parent is interrupted and its worker freed (the children have already invested more).
    let mut parent_cutoff = 1.0f64;
    let mut exact_count = false;
    let mut fresh_assumptions = false;
    let mut fixed_units = false;
    let mut check_shared = false;
    let mut share_pool = false;
    let mut share_max_size = 8usize;
    let mut share_max_lbd = 0u32;
    let mut probes = 100usize;
    let mut est_study: Vec<usize> = Vec::new();
    let mut est_only = false;
    let mut score_k = 0usize;
    let mut score_factor = 10.0f64;
    let mut score_min_total = 1e8f64;
    let mut score_rounds = 3usize;
    // Overrun split: a running cube whose time exceeds FACTOR x (its estimate x the measured
    // seconds-per-estimated-node) and at least MIN seconds is split; its parts go to the front
    // of the queue and the original is interrupted (its progress is unreliable when the estimate
    // is that far off). 2026-11-03: g36 cube 4 (est 3.9% of total) ran 3.5 h untouched.
    // Not adopted as a default (user decision 2026-11-03): pre-splitting at generation covers
    // oversized cubes; the runtime monitor stays opt-in for experiments.
    let mut overrun = 0.0f64;
    let mut overrun_min = 60.0f64;
    while let Some(a) = args.next() {
        match a.as_str() {
            "--rules" => {
                options.rules = args
                    .next()
                    .expect("--rules requires off or a comma-separated list of diag,wedge,g2")
                    .parse()
                    .unwrap_or_else(|e| panic!("{e}"))
            }
            "--assumptions" => assumptions = true,
            "--share-every" => {
                share_every = args
                    .next()
                    .expect("--share-every requires K (0 disables sharing)")
                    .parse()
                    .unwrap()
            }
            "--verify-cubes" => verify_cubes = true,
            "--budget" => {
                budget = args
                    .next()
                    .expect("--budget requires a conflict count (0 disables re-splitting)")
                    .parse()
                    .unwrap()
            }
            "--resplit" => resplit = args.next().and_then(|v| v.parse().ok()).unwrap_or(4),
            "--balance" => {
                balance = args
                    .next()
                    .expect("--balance requires a slack factor (split cubes larger than total/(threads*slack))")
                    .parse()
                    .unwrap()
            }
            "--no-steal" => steal = false,
            "--exact-count" => exact_count = true,
            "--fresh-assumptions" => fresh_assumptions = true,
            "--fixed-units" => fixed_units = true,
            "--check-shared" => check_shared = true,
            "--share-pool" => share_pool = true,
            "--share-max-size" => share_max_size = args.next().expect("--share-max-size requires N").parse().unwrap(),
            "--share-max-lbd" => share_max_lbd = args.next().expect("--share-max-lbd requires N (0 disables cap)").parse().unwrap(),
            "--steal" => steal = true,
            "--steal-min" => steal_min = args.next().and_then(|v| v.parse().ok()).unwrap_or(20.0),
            "--parent-cutoff" => parent_cutoff = args.next().and_then(|v| v.parse().ok()).unwrap_or(1.0),
            "--balance-verify" => balance_verify = args.next().and_then(|v| v.parse().ok()).unwrap_or(2.0),
            "--verify-floor" => verify_floor = args.next().and_then(|v| v.parse().ok()).unwrap_or(1e6),
            "--verify-min" => verify_min = args.next().and_then(|v| v.parse().ok()).unwrap_or(2.0),
            "--balance-mean" => balance_mean = args.next().and_then(|v| v.parse().ok()).unwrap_or(4.0),
            "--probes" => probes = args.next().and_then(|v| v.parse().ok()).unwrap_or(100),
            "--est-study" => est_study = args.next().map(|v| v.split(',').filter_map(|s| s.trim().parse().ok()).collect()).unwrap_or_default(),
            "--est-only" => est_only = true,
            "--score" => score_k = args.next().and_then(|v| v.parse().ok()).unwrap_or(3),
            "--score-factor" => score_factor = args.next().and_then(|v| v.parse().ok()).unwrap_or(10.0),
            "--score-min-total" => score_min_total = args.next().and_then(|v| v.parse().ok()).unwrap_or(1e8),
            "--score-rounds" => score_rounds = args.next().and_then(|v| v.parse().ok()).unwrap_or(3),
            "--overrun" => overrun = args.next().and_then(|v| v.parse().ok()).unwrap_or(10.0),
            "--overrun-min" => overrun_min = args.next().and_then(|v| v.parse().ok()).unwrap_or(60.0),
            "--cube-rules" => match args.next().as_deref() {
                Some("off") => cube_options = SolveOptions::default(),
                Some("strong") => {
                    cube_options = strong_options();
                }
                _ => panic!("--cube-rules requires off or strong"),
            },
            "--cube-order" => match args.next().as_deref() {
                Some("big-first") => big_first = true,
                Some("default") => big_first = false,
                _ => panic!("--cube-order requires default or big-first"),
            },
            "--short-only" => options.short_only = true,
            "--edges-only" => options.edges_only = true,
            "--log-encoding" => options.log_encoding = true,
            "--full-cover" => options.full_cover = true,
            "--threads" | "-j" => threads = args.next().and_then(|v| v.parse().ok()).unwrap_or(4),
            "--cubes-file" => cubes_file = Some(args.next().expect("--cubes-file requires FILE")),
            "--cube-stats" => cube_stats = Some(args.next().expect("--cube-stats requires FILE")),
            "--dump-cubes" => dump_cubes = Some(args.next().expect("--dump-cubes requires FILE")),
            "--cubes" => cubes = args.next().and_then(|v| v.parse().ok()).unwrap_or(64),
            "--transform" => transform = args.next().and_then(|v| v.parse().ok()).unwrap_or(0),
            "--max" => max = args.next().and_then(|v| v.parse().ok()).unwrap_or(2),
            "--rnd-freq" => rnd_freq = args.next().and_then(|v| v.parse().ok()),
            "--reduce-db" => {
                let v = args.next().expect("--reduce-db FIRST,INC");
                let mut it = v.split(',').map(|x| x.parse::<i32>().unwrap());
                reduce_db = Some((it.next().unwrap(), it.next().unwrap_or(300)));
            }
            _ => url = Some(a),
        }
    }
    let url = url.expect("usage: numlin_sat_cube [--rules off|diag|wedge|g2|diag,wedge,g2] [--full-cover] [--short-only] [--log-encoding] [--threads N] [--cubes M] [--transform K] [--max A] [--cube-rules strong|off (default strong)] [--cube-order default|big-first] [--assumptions] [--share-every K] [--budget CONFLICTS] [--resplit N] [--balance SLACK] [--balance-mean N] [--balance-verify F] [--verify-min M] [--verify-floor N] [--probes P] [--est-study P1,P2,...] [--est-only] [--score K] [--score-factor F (10)] [--score-min-total T (1e8)] [--score-rounds R (3)] [--no-steal] [--steal-min SECS (default 20)] [--parent-cutoff F (default 1, 0 = off)] [--overrun FACTOR (default 0 = off)] [--overrun-min SECS (default 60)] [--exact-count] [--fresh-assumptions] [--fixed-units] [--share-pool] [--share-max-size N] [--share-max-lbd N] [--check-shared] [--edges-only] [--rnd-freq F] [--reduce-db FIRST,INC] [--verify-cubes] URL");
    if options.short_only {
        max = 1;
    }
    assert!(threads > 0);
    fixed_units |= share_pool;
    assert!(share_max_size > 0 && share_max_size <= i32::MAX as usize);
    assert!(
        !fixed_units || (!assumptions && !fresh_assumptions),
        "--fixed-units conflicts with assumption modes"
    );
    assert!(
        !check_shared || fixed_units,
        "--check-shared requires --fixed-units"
    );
    let started = Instant::now();
    assert!(transform < 8, "--transform must be 0..7");
    let problem = Problem::from_url(&url, transform).unwrap_or_else(|e| panic!("{e}"));
    let h = problem.height();
    let w = problem.width();
    let clues: Vec<Vec<Option<i32>>> = (0..h)
        .map(|y| (0..w).map(|x| problem[(y, x)]).collect())
        .collect();
    // The row-scan splitter uses shortening canonicalizations of its own.
    // Full-cover enumeration must start from the unrestricted SAT board.
    if rnd_freq.is_some() || reduce_db.is_some() {
        Config::set_default(Config {
            glucose_random_var_freq: rnd_freq,
            glucose_reduce_db: reduce_db,
            ..Config::default()
        });
    }
    if budget > 0 && !assumptions {
        panic!("--budget requires --assumptions");
    }
    let mut split_found = 0usize;
    let mut cube_list: Vec<Cube> = if let Some(path) = &cubes_file {
        let (list, extra) = read_cubes(path, w, h, transform).unwrap_or_else(|e| panic!("{e}"));
        split_found = extra;
        println!("cube source: file {path} ({} cubes)", list.len());
        if balance > 0.0 {
            let (list, extra) = balance_external(
                &problem,
                list,
                threads,
                balance,
                balance_mean,
                balance_verify,
                verify_min,
                verify_floor,
                probes,
                &cube_options,
            );
            split_found += extra;
            list
        } else {
            list
        }
    } else if options.full_cover {
        vec![Cube {
            edges: vec![],
            next: 0,
            weight: 0.0,
        }]
    } else if balance > 0.0 {
        let (list, extra) = generate_cubes_balanced_verify_floor(
            problem.clone(),
            cubes,
            threads,
            balance,
            balance_mean,
            balance_verify,
            verify_min,
            verify_floor,
            probes,
            1 << 15,
            &cube_options,
        );
        split_found = extra;
        list
    } else {
        let (list, extra) = split_cube(
            problem.clone(),
            &Cube {
                edges: vec![],
                next: 0,
                weight: 0.0,
            },
            cubes,
            &cube_options,
        );
        split_found = extra;
        list
    };
    // Score pass (--score K): the generation-time estimate of an accepted cube is biased low
    // (a cube is accepted when its estimate came out under the limit) and a heavy cube's
    // estimate is bimodal (small most of the time, huge when a probe hits the heavy branch).
    // So re-estimate every cube K times independently, take the MAX as its score, and split any
    // cube whose score is >= score_factor x the mean score (and >= verify_floor), unconditionally.
    // Children are scored and re-checked for up to score_rounds rounds. Only runs when the
    // generation-time total estimate is >= score_min_total (so small boards pay nothing).
    if score_k > 0 && balance > 0.0 {
        let total0: f64 = cube_list.iter().map(|c| c.weight).sum();
        if total0 >= score_min_total {
            let t0 = Instant::now();
            let problem_ref = &problem;
            let cube_options_ref = &cube_options;
            let nthr = threads.max(1);
            let score_of = |cubes: &[Cube], round: usize| -> Vec<f64> {
                std::thread::scope(|s| {
                    let hs: Vec<_> = (0..nthr)
                        .map(|w| {
                            s.spawn(move || {
                                let mut out = Vec::new();
                                for (i, c) in cubes.iter().enumerate() {
                                    if i % nthr != w {
                                        continue;
                                    }
                                    let m = (0..score_k)
                                        .map(|k| {
                                            estimate_cube_size(
                                                problem_ref,
                                                c,
                                                probes,
                                                7_777_777
                                                    + (round as u64) * 1_000_003
                                                    + (k as u64) * 7_919
                                                    + (i as u64) * 104_729,
                                                cube_options_ref,
                                            )
                                        })
                                        .fold(0.0f64, f64::max);
                                    out.push((i, m));
                                }
                                out
                            })
                        })
                        .collect();
                    let mut all = vec![0.0f64; cubes.len()];
                    for h in hs {
                        for (i, m) in h.join().unwrap() {
                            all[i] = m;
                        }
                    }
                    all
                })
            };
            let mut scores = score_of(&cube_list, 0);
            let mean_score = scores.iter().sum::<f64>() / scores.len().max(1) as f64;
            let n0 = cube_list.len();
            let mut split_total = 0usize;
            let mut gen_log: Vec<String> = Vec::new();
            for round in 1..=score_rounds {
                // Threshold is relative to the generation-time mean (a stable reference); the mean
                // of the max-of-K scores is inflated by the heavy tail and would under-split.
                let gen_mean = total0 / n0.max(1) as f64;
                let thr = (score_factor * gen_mean).max(verify_floor);
                let mut keep: Vec<Cube> = Vec::new();
                let mut keep_scores: Vec<f64> = Vec::new();
                let mut to_split: Vec<(usize, Cube, f64)> = Vec::new();
                for (i, (c, &sc)) in cube_list.drain(..).zip(scores.iter()).enumerate() {
                    if sc >= thr {
                        to_split.push((i, c, sc));
                    } else {
                        keep.push(c);
                        keep_scores.push(sc);
                    }
                }
                if to_split.is_empty() {
                    cube_list = keep;
                    scores = keep_scores;
                    break;
                }
                let mut children_all: Vec<Cube> = Vec::new();
                let mut fam: Vec<(usize, f64, f64, usize)> = Vec::new();
                for (i, c, sc) in to_split {
                    let (parts, extra) = split_cube(problem.clone(), &c, 2, cube_options_ref);
                    if parts.len() == 1 {
                        // unsplittable: keep as is (score is what it is)
                        gen_log.push(format!("[score] round {round}: cube {} est {:.2e} score {:.2e} ({:.1}x gen mean): unsplittable", if round == 1 { i.to_string() } else { "-".to_string() }, c.weight, sc, sc / gen_mean.max(1.0)));
                        keep.push(c);
                        keep_scores.push(sc);
                        continue;
                    }
                    split_found += extra;
                    fam.push((i, c.weight, sc, parts.len()));
                    children_all.extend(parts);
                }
                let child_scores = score_of(&children_all, round);
                let mut off = 0usize;
                for (i, w, sc, n) in fam {
                    let csum: f64 = child_scores[off..off + n].iter().sum();
                    gen_log.push(format!("[score] round {round}: cube {} est {:.2e} score {:.2e} ({:.1}x gen mean) -> {n} children, score sum {:.2e}", if round == 1 { i.to_string() } else { "-".to_string() }, w, sc, sc / gen_mean.max(1.0), csum));
                    off += n;
                    split_total += 1;
                }
                for (c, sc) in children_all.into_iter().zip(child_scores.iter()) {
                    let mut c = c;
                    c.weight = *sc;
                    keep.push(c);
                    keep_scores.push(*sc);
                }
                cube_list = keep;
                scores = keep_scores;
            }
            for (c, &sc) in cube_list.iter_mut().zip(scores.iter()) {
                c.weight = sc;
            }
            cube_list.sort_by(|a, b| b.weight.partial_cmp(&a.weight).unwrap());
            for l in &gen_log {
                eprintln!("{l}");
            }
            eprintln!(
                "[score] K={score_k} probes {probes}: mean score {mean_score:.3e} (gen mean {:.3e}, x{:.1}); threshold {:.1}x gen mean, floor {verify_floor:.0e}; split {split_total} cubes, {n0} -> {} cubes, in {:.2?}",
                total0 / n0.max(1) as f64,
                mean_score / (total0 / n0.max(1) as f64).max(1e-9),
                score_factor,
                cube_list.len(),
                t0.elapsed()
            );
        } else {
            eprintln!("[score] skipped: total est {total0:.3e} < {score_min_total:.0e}");
        }
    }

    // Fewer fixed edges means more undecided edges on the same board.
    if big_first && balance <= 0.0 {
        cube_list.sort_by_key(|c| c.edges.len());
    }
    if let Some(path) = &dump_cubes {
        write_cubes(
            path,
            &cube_list,
            w,
            h,
            transform,
            split_found,
            started.elapsed().as_secs_f64(),
        );
    }
    let stats_enabled = cube_stats.is_some();
    let n_cubes = cube_list.len();
    let started_at = started;
    let gen_time = started.elapsed();
    println!("transform: {}", TRANSFORM_NAMES[transform]);
    println!("cubes: {n_cubes} (generated in {:.3?})", gen_time);
    if split_found > 0 {
        println!("solutions completed while splitting: {split_found}");
    }
    if balance > 0.0 {
        let total: f64 = cube_list.iter().map(|c| c.weight).sum();
        let largest = cube_list.first().map(|c| c.weight).unwrap_or(0.0);
        let mean = total / cube_list.len().max(1) as f64;
        println!(
            "balance: total est {:.3e}, largest cube {:.3e} ({:.1}% of total, limit {:.1}%; mean {:.3e}, largest = {:.1}x mean{})",
            total,
            largest,
            100.0 * largest / total.max(1.0),
            if balance_mean > 0.0 { f64::NAN } else { 100.0 / (threads as f64 * balance) },
            mean,
            largest / mean.max(1.0),
            if balance_mean > 0.0 { format!(", limit {balance_mean}x initial mean") } else { String::new() }
        );
    }

    // Estimate study: re-estimate every generated cube with several probe counts (each with its
    // own seed) and print them, so the estimator's sampling noise and its correlation with the
    // actual solve time can be measured offline ("[est] cube ID est E probes a,b,c -> x y z").
    if !est_study.is_empty() {
        let spec = est_study.clone();
        let problem_ref = &problem;
        let cube_options_ref = &cube_options;
        let cubes_ref = &cube_list;
        let t0 = Instant::now();
        let results: Vec<Vec<f64>> = std::thread::scope(|s| {
            let handles: Vec<_> = (0..threads.max(1))
                .map(|w| {
                    let spec = spec.clone();
                    s.spawn(move || {
                        let mut out = Vec::new();
                        for (i, c) in cubes_ref.iter().enumerate() {
                            if i % threads.max(1) != w {
                                continue;
                            }
                            let v: Vec<f64> = spec
                                .iter()
                                .enumerate()
                                .map(|(k, &pr)| {
                                    estimate_cube_size(
                                        problem_ref,
                                        c,
                                        pr,
                                        1_000_003 + (k as u64) * 7_919 + (i as u64) * 104_729,
                                        cube_options_ref,
                                    )
                                })
                                .collect();
                            out.push((i, v));
                        }
                        out
                    })
                })
                .collect();
            let mut all = vec![Vec::new(); cubes_ref.len()];
            for h in handles {
                for (i, v) in h.join().unwrap() {
                    all[i] = v;
                }
            }
            all
        });
        let spec_s: Vec<String> = spec.iter().map(|p| p.to_string()).collect();
        for (i, c) in cube_list.iter().enumerate() {
            let vals: Vec<String> = results[i].iter().map(|v| format!("{v:.3e}")).collect();
            eprintln!(
                "[est] cube {i} depth 0 est {:.3e} probes {} -> {}",
                c.weight,
                spec_s.join(","),
                vals.join(" ")
            );
        }
        println!(
            "est-study: {} cubes x probes {} in {:.3?}",
            cube_list.len(),
            spec_s.join(","),
            t0.elapsed()
        );
        if est_only {
            return;
        }
    }

    let pool = Mutex::new(ClausePool::default());
    let pool_ref = &pool;
    let stop = AtomicBool::new(false);
    let stop_ref = &stop;
    // Scheduler state. Every cube is a node; an idle worker may split a running node
    // ("steal"): its children are solved by the idle workers while the original keeps
    // running, and whichever side finishes first settles the node (the other is interrupted
    // or dropped). Answers are counted over resolved nodes without a resolved ancestor.
    struct Node {
        cube: Cube,
        parent: Option<usize>,
        depth: usize,
        remaining: usize,
        resolved: bool,
        split: bool,
        abandoned: bool,
        cutoff: bool,
        spent: f64,
        answers: usize,
        worker: Option<usize>,
        owner: Option<usize>,
        started: Option<Instant>,
    }
    struct Sched {
        nodes: Vec<Node>,
        queue: VecDeque<usize>,
        running: Vec<usize>,
        handles: Vec<Option<InterruptHandle>>,
        found: usize,
        solved: usize,
        splits: usize,
        steals: usize,
        overruns: usize,
        wasted: f64,
        cutoffs: usize,
        // Measured cost: seconds per estimated node, over completed estimated cubes.
        rate_spent: f64,
        rate_weight: f64,
        stats: std::collections::BTreeMap<usize, json::JsonValue>,
    }
    impl Sched {
        fn ancestor_resolved(&self, mut id: usize) -> bool {
            while let Some(p) = self.nodes[id].parent {
                if self.nodes[p].resolved {
                    return true;
                }
                id = p;
            }
            false
        }
        fn recount(&mut self, base: usize) {
            let mut n = base;
            for id in 0..self.nodes.len() {
                if self.nodes[id].resolved && !self.ancestor_resolved(id) {
                    n += self.nodes[id].answers;
                }
            }
            self.found = n;
        }
        fn interrupt_running_below(&mut self, id: usize) {
            for &r in &self.running {
                if r != id {
                    let mut a = r;
                    let mut below = false;
                    while let Some(p) = self.nodes[a].parent {
                        if p == id {
                            below = true;
                            break;
                        }
                        a = p;
                    }
                    if below {
                        if let Some(w) = self.nodes[r].worker {
                            if let Some(h) = self.handles[w] {
                                h.interrupt();
                            }
                        }
                    }
                }
            }
        }
        /// Mark `id` resolved with `answers`; propagate to the parent when all siblings are done.
        fn complete(&mut self, id: usize, answers: usize) {
            if self.nodes[id].resolved {
                return;
            }
            self.nodes[id].resolved = true;
            self.nodes[id].answers = answers;
            // Children still running are now redundant.
            self.interrupt_running_below(id);
            if let Some(p) = self.nodes[id].parent {
                self.nodes[p].remaining -= 1;
                if self.nodes[p].remaining == 0 && !self.nodes[p].resolved {
                    let sum: usize = (0..self.nodes.len())
                        .filter(|&c| self.nodes[c].parent == Some(p) && self.nodes[c].resolved)
                        .map(|c| self.nodes[c].answers)
                        .sum();
                    // The parent's own solve is now redundant.
                    if let Some(w) = self.nodes[p].worker {
                        if let Some(h) = self.handles[w] {
                            h.interrupt();
                        }
                    }
                    self.complete(p, sum);
                }
            }
        }
    }
    let sched = Mutex::new(Sched {
        nodes: cube_list
            .into_iter()
            .map(|c| Node {
                cube: c,
                parent: None,
                depth: 0,
                remaining: 0,
                resolved: false,
                split: false,
                abandoned: false,
                cutoff: false,
                spent: 0.0,
                answers: 0,
                owner: None,
                worker: None,
                started: None,
            })
            .collect(),
        queue: (0..n_cubes).collect(),
        running: Vec::new(),
        handles: vec![None; threads],
        found: split_found,
        solved: 0,
        splits: 0,
        steals: 0,
        overruns: 0,
        wasted: 0.0,
        cutoffs: 0,
        rate_spent: 0.0,
        rate_weight: 0.0,
        stats: std::collections::BTreeMap::new(),
    });
    let sched_ref = &sched;
    let clues_ref = &clues;
    let problem_ref = &problem;
    let cube_options_ref = &cube_options;
    let to_fixed = |cube: &Cube| -> Vec<FixedEdge> { cube.to_fixed_edges() };
    let to_fixed = &to_fixed;
    let per_thread: Vec<f64> = std::thread::scope(|s| {
        if parent_cutoff > 0.0 && steal {
            // Parent-cutoff monitor: a stolen parent is interrupted once its children's busy time
            // (finished children's time + running children's elapsed) exceeds parent_cutoff x its
            // own running time. Simple by design: no queue condition, no estimate involved.
            s.spawn(move || loop {
                std::thread::sleep(std::time::Duration::from_secs(2));
                if stop_ref.load(Ordering::Relaxed) {
                    break;
                }
                let mut g = sched_ref.lock().unwrap();
                if g.running.is_empty() && g.queue.is_empty() {
                    break;
                }
                let victims: Vec<(usize, f64, f64, usize)> = g
                    .running
                    .iter()
                    .copied()
                    .filter(|&r| {
                        let n = &g.nodes[r];
                        n.split && !n.resolved && !n.abandoned && !g.ancestor_resolved(r)
                    })
                    .filter_map(|r| {
                        let own = g.nodes[r].started.map(|t| t.elapsed().as_secs_f64()).unwrap_or(0.0);
                        let mut kids = 0.0f64;
                        let mut nk = 0usize;
                        for (c, n) in g.nodes.iter().enumerate() {
                            if n.parent == Some(r) {
                                nk += 1;
                                kids += if n.worker.is_some() {
                                    n.started.map(|t| t.elapsed().as_secs_f64()).unwrap_or(0.0)
                                } else {
                                    n.spent
                                };
                                let _ = c;
                            }
                        }
                        if nk > 0 && kids > parent_cutoff * own { Some((r, own, kids, nk)) } else { None }
                    })
                    .collect();
                for (v, own, kids, nk) in victims {
                    g.nodes[v].abandoned = true;
                    g.nodes[v].cutoff = true;
                    g.cutoffs += 1;
                    if let Some(w) = g.nodes[v].worker {
                        if let Some(h) = g.handles[w] {
                            h.interrupt();
                        }
                    }
                    eprintln!(
                        "[cutoff] cube {v} (depth {}) running {:.0}s, its {nk} children busy {:.0}s > {parent_cutoff}x -> parent interrupted, elapsed {:.0}s",
                        g.nodes[v].depth, own, kids, started_at.elapsed().as_secs_f64()
                    );
                }
            });
        }
        if overrun > 0.0 {
            // Overrun monitor: splits a running cube that has exceeded `overrun` x its expected
            // time (and `overrun_min` s), queues the parts first and interrupts the original.
            s.spawn(move || loop {
                std::thread::sleep(std::time::Duration::from_secs(2));
                if stop_ref.load(Ordering::Relaxed) {
                    break;
                }
                let victim = {
                    let g = sched_ref.lock().unwrap();
                    if g.running.is_empty() && g.queue.is_empty() {
                        break;
                    }
                    if g.rate_weight <= 0.0 || g.solved < 3 {
                        continue;
                    }
                    let rate = g.rate_spent / g.rate_weight;
                    g.running
                        .iter()
                        .copied()
                        .filter(|&r| {
                            let n = &g.nodes[r];
                            !n.split && !n.resolved && n.cube.weight > 0.0 && !g.ancestor_resolved(r)
                        })
                        .filter_map(|r| {
                            let n = &g.nodes[r];
                            let running_for = n.started.map(|t| t.elapsed().as_secs_f64()).unwrap_or(0.0);
                            let expected = n.cube.weight * rate;
                            if running_for >= overrun_min && running_for > overrun * expected {
                                Some((r, running_for, expected))
                            } else {
                                None
                            }
                        })
                        .max_by(|a, b| a.1.partial_cmp(&b.1).unwrap())
                };
                let Some((v, running_for, expected)) = victim else { continue };
                let (vc, vd) = {
                    let mut g = sched_ref.lock().unwrap();
                    if g.nodes[v].split || g.nodes[v].resolved {
                        continue;
                    }
                    g.nodes[v].split = true;
                    (g.nodes[v].cube.clone(), g.nodes[v].depth)
                };
                let (parts, extra) = split_cube(problem_ref.clone(), &vc, resplit, cube_options_ref);
                let parts: Vec<Cube> = parts
                    .into_iter()
                    .enumerate()
                    .map(|(i, mut c)| {
                        c.weight = estimate_cube_size(problem_ref, &c, probes, 11 + i as u64, cube_options_ref);
                        c
                    })
                    .collect();
                let mut parts = parts;
                parts.sort_by(|a, b| b.weight.partial_cmp(&a.weight).unwrap());
                let mut g = sched_ref.lock().unwrap();
                g.overruns += 1;
                if g.nodes[v].resolved {
                    continue;
                }
                // Stop the original now: an estimate this far off says nothing about its progress.
                g.nodes[v].abandoned = true;
                if let Some(w) = g.nodes[v].worker {
                    if let Some(h) = g.handles[w] {
                        h.interrupt();
                    }
                }
                if parts.is_empty() {
                    g.complete(v, extra);
                    g.recount(split_found);
                    eprintln!(
                        "[overrun] cube {v} (depth {vd}, est {:.2e}, expected {:.0}s) running {:.0}s: exhausted by the split ({extra} sol), elapsed {:.0}s",
                        vc.weight, expected, running_for, started_at.elapsed().as_secs_f64()
                    );
                    continue;
                }
                let n_parts = parts.len();
                let est_sum: f64 = parts.iter().map(|c| c.weight).sum();
                g.nodes[v].remaining = n_parts;
                let mut ids = Vec::with_capacity(n_parts);
                for part in parts {
                    let id = g.nodes.len();
                    g.nodes.push(Node { cube: part, parent: Some(v), depth: vd + 1, remaining: 0, resolved: false, split: false, abandoned: false, cutoff: false, spent: 0.0, answers: 0, owner: None, worker: None, started: None });
                    ids.push(id);
                }
                for &id in ids.iter().rev() {
                    g.queue.push_front(id);
                }
                if extra > 0 {
                    g.nodes[v].answers = extra;
                    let id = g.nodes.len();
                    g.nodes.push(Node { cube: Cube { edges: vec![], next: 0, weight: 0.0 }, parent: Some(v), depth: vd + 1, remaining: 0, resolved: true, split: false, abandoned: false, cutoff: false, spent: 0.0, answers: extra, owner: None, worker: None, started: None });
                    let _ = id;
                }
                eprintln!(
                    "[overrun] cube {v} (depth {vd}, est {:.2e}, expected {:.0}s) running {:.0}s > {overrun}x -> {n_parts} parts (est sum {:.2e}), original interrupted, queue {}, elapsed {:.0}s",
                    vc.weight, expected, running_for, est_sum, g.queue.len(), started_at.elapsed().as_secs_f64()
                );
            });
        }
        let handles: Vec<_> = (0..threads)
            .map(|worker| {
                s.spawn(move || {
                    let built = Instant::now();
                    let mut incremental = if assumptions {
                        Some(NumlinAssumptionSolver::new(clues_ref, options))
                    } else {
                        None
                    };
                    if let Some(solver) = &mut incremental {
                        sched_ref.lock().unwrap().handles[worker] = Some(solver.interrupt_handle());
                    }
                    let mut cursor = 0;
                    let mut checker = check_shared.then(|| NumlinAssumptionSolver::new(clues_ref, options));
                    let mut completed = 0;
                    let mut busy = built.elapsed().as_secs_f64();
                    loop {
                        if stop_ref.load(Ordering::Relaxed) {
                            break;
                        }
                        // Fetch work, or steal from a running node when the queue is empty.
                        let (id, depth, cube) = {
                            let mut g = sched_ref.lock().unwrap();
                            if g.found >= max {
                                stop_ref.store(true, Ordering::Relaxed);
                                break;
                            }
                            let mut picked = None;
                            while let Some(id) = g.queue.pop_front() {
                                if g.nodes[id].resolved || g.ancestor_resolved(id) {
                                    continue;
                                }
                                picked = Some(id);
                                break;
                            }
                            match picked {
                                Some(id) => {
                                    g.nodes[id].worker = Some(worker);
                                    g.nodes[id].owner = Some(worker);
                                    g.nodes[id].started = Some(Instant::now());
                                    g.running.push(id);
                                    // Start line for dashboards: which worker holds which cube.
                                    let parent = g.nodes[id].parent.map(|p| p.to_string()).unwrap_or_else(|| "-".to_string());
                                    // Fingerprint of the fixed-edge set so the same cube can be recognised across runs
                                    // whose numbering differs (2026-11-04).
                                    let fp = {
                                        let mut h: u64 = 0xcbf2_9ce4_8422_2325;
                                        for &(y, x, v) in &g.nodes[id].cube.edges {
                                            for b in [y as u64, x as u64, v as u64] {
                                                h ^= b.wrapping_add(1);
                                                h = h.wrapping_mul(0x0000_0100_0000_01b3);
                                            }
                                        }
                                        h
                                    };
                                    eprintln!(
                                        "[start] worker {worker} cube {id} (depth {}, est {:.2e}, parent {parent}, fp {fp:016x}, fixed {}), elapsed {:.0}s",
                                        g.nodes[id].depth, g.nodes[id].cube.weight, g.nodes[id].cube.edges.len(), started_at.elapsed().as_secs_f64()
                                    );
                                    (id, g.nodes[id].depth, g.nodes[id].cube.clone())
                                }
                                None => {
                                    if g.running.is_empty() {
                                        break;
                                    }
                                    if !steal {
                                        drop(g);
                                        std::thread::sleep(std::time::Duration::from_millis(20));
                                        continue;
                                    }
                                    // Victim: the running, unsplit node with the largest estimate
                                    // (ties: longest running).
                                    let victim = g
                                        .running
                                        .iter()
                                        .copied()
                                        .filter(|&r| !g.nodes[r].split && !g.nodes[r].resolved)
                                        .filter(|&r| g.nodes[r].started.map(|t| t.elapsed().as_secs_f64()).unwrap_or(0.0) >= steal_min)
                                        .max_by(|&x, &y| {
                                            let nx = &g.nodes[x];
                                            let ny = &g.nodes[y];
                                            nx.cube
                                                .weight
                                                .partial_cmp(&ny.cube.weight)
                                                .unwrap()
                                                .then(
                                                    ny.started
                                                        .unwrap()
                                                        .cmp(&nx.started.unwrap()),
                                                )
                                        });
                                    let Some(v) = victim else {
                                        drop(g);
                                        std::thread::sleep(std::time::Duration::from_millis(20));
                                        continue;
                                    };
                                    g.nodes[v].split = true;
                                    let vc = g.nodes[v].cube.clone();
                                    let vd = g.nodes[v].depth;
                                    drop(g);
                                    let (parts, extra) = split_cube(
                                        problem_ref.clone(),
                                        &vc,
                                        resplit,
                                        cube_options_ref,
                                    );
                                    let mut g = sched_ref.lock().unwrap();
                                    g.steals += 1;
                                    if g.nodes[v].resolved {
                                        continue;
                                    }
                                    if parts.is_empty() {
                                        // The split exhausted the node: it is settled by the split.
                                        if let Some(w) = g.nodes[v].worker {
                                            if let Some(h) = g.handles[w] {
                                                h.interrupt();
                                            }
                                        }
                                        g.complete(v, extra);
                                        g.recount(split_found);
                                        continue;
                                    }
                                    let n_parts = parts.len();
                                    g.nodes[v].remaining = n_parts;
                                    let mut ids = Vec::with_capacity(n_parts);
                                    drop(g);
                                    let parts: Vec<Cube> = parts
                                        .into_iter()
                                        .enumerate()
                                        .map(|(i, mut c)| {
                                            c.weight = estimate_cube_size(problem_ref, &c, probes, 7 + i as u64, cube_options_ref);
                                            c
                                        })
                                        .collect();
                                    // Heaviest first among the parts too (2026-11-03): the split emits them in
                                    // row-scan order, which says nothing about their size.
                                    let mut parts = parts;
                                    parts.sort_by(|a, b| b.weight.partial_cmp(&a.weight).unwrap());
                                    let mut g = sched_ref.lock().unwrap();
                                    for part in parts {
                                        let id = g.nodes.len();
                                        g.nodes.push(Node {
                                            cube: part,
                                            parent: Some(v),
                                            depth: vd + 1,
                                            remaining: 0,
                                            resolved: false,
                                            split: false,
                                            abandoned: false, cutoff: false, spent: 0.0,
                                            answers: 0,
                                            owner: None,
            worker: None,
                                            started: None,
                                        });
                                        ids.push(id);
                                    }
                                    for &id in ids.iter().rev() {
                                        g.queue.push_front(id);
                                    }
                                    if extra > 0 {
                                        // Solutions completed during the split belong to the node
                                        // but to none of its parts: keep them in a resolved leaf.
                                        let id = g.nodes.len();
                                        g.nodes.push(Node {
                                            cube: Cube { edges: vec![], next: 0, weight: 0.0 },
                                            parent: Some(v),
                                            depth: vd + 1,
                                            remaining: 0,
                                            resolved: true,
                                            split: false,
                                            abandoned: false, cutoff: false, spent: 0.0,
                                            answers: extra,
                                            owner: None,
            worker: None,
                                            started: None,
                                        });
                                        g.nodes[v].remaining += 1;
                                        g.nodes[v].remaining -= 1;
                                        let _ = id;
                                    }
                                    let running_for = g.nodes[v].started.map(|t| t.elapsed().as_secs_f64()).unwrap_or(0.0);
                                    eprintln!(
                                        "[steal] worker {worker} split running cube {v} (depth {vd}, est {:.2e}, running {:.1}s) -> {n_parts} parts, queue {}, elapsed {:.0}s",
                                        vc.weight,
                                        running_for,
                                        g.queue.len(),
                                        started_at.elapsed().as_secs_f64()
                                    );
                                    continue;
                                }
                            }
                        };
                        let fixed = to_fixed(&cube);
                        let t = Instant::now();
                        let limit = if budget > 0 { Some(budget) } else { None };
                        let mut sat_counts: Option<(u64,u64,u64)> = None;
                        let result: Option<Vec<_>> = if let Some(solver) = &mut incremental {
                            if share_every > 0 && completed % share_every == 0 {
                                pool_ref
                                    .lock()
                                    .unwrap()
                                    .exchange(worker, solver, &mut cursor);
                            }
                            let before=stats_enabled.then(||solver.search_stats());
                            let result=solver.solve_cube_limited(&fixed, max, limit);
                            if let Some(b)=before {let a=solver.search_stats();sat_counts=Some((a.0-b.0,a.1-b.1,a.2-b.2));}
                            result
                        } else if fresh_assumptions {
                            // Fresh solver per cube, fixed edges as assumptions: the encoding is
                            // identical across cubes, so learned clauses can be shared soundly.
                            let mut fresh = NumlinAssumptionSolver::new(clues_ref, options);
                            let mut cur = 0;
                            if share_every > 0 {
                                pool_ref.lock().unwrap().exchange(worker, &mut fresh, &mut cur);
                            }
                            sched_ref.lock().unwrap().handles[worker] = Some(fresh.interrupt_handle());
                            let before=stats_enabled.then(||fresh.search_stats());
                            let r = fresh.solve_cube_limited(&fixed, max, limit);
                            if let Some(b)=before {let a=fresh.search_stats();sat_counts=Some((a.0-b.0,a.1-b.1,a.2-b.2));}
                            sched_ref.lock().unwrap().handles[worker] = None;
                            if share_every > 0 {
                                pool_ref.lock().unwrap().exchange(worker, &mut fresh, &mut cur);
                            }
                            r
                        } else {
                            // Fresh solver per cube with the fixed edges as unit constraints;
                            // interruptible so that idle workers can take over its parts.
                            let mut fresh = if fixed_units {
                                // Raw IDs must match before imports or cube units are added.
                                let mut fresh = NumlinAssumptionSolver::with_fixed_units(clues_ref, &[], options);
                                if share_pool {
                                    let imported = pool_ref.lock().unwrap().snapshot(&fresh);
                                    for clause in imported { fresh.add_learnt(&clause); }
                                }
                                fresh.add_fixed_units(&fixed);
                                fresh
                            } else {
                                NumlinAssumptionSolver::with_fixed(clues_ref, &fixed, options)
                            };
                            sched_ref.lock().unwrap().handles[worker] = Some(fresh.interrupt_handle());
                            let before=stats_enabled.then(||fresh.search_stats());
                            let r = fresh.solve_cube_limited(&[], max, limit);
                            if let Some(b)=before {let a=fresh.search_stats();sat_counts=Some((a.0-b.0,a.1-b.1,a.2-b.2));}
                            sched_ref.lock().unwrap().handles[worker] = None;
                            if fixed_units {
                                let (learned, independent) = fresh.dependency_learnt_counts();
                                let mut checked = 0;
                                let exported = if share_pool || check_shared {
                                    fresh.independent_learnts(share_max_size, share_max_lbd)
                                } else { vec![] };
                                if let Some(checker) = &mut checker {
                                    assert_eq!(checker.encoding_fingerprint(), fresh.encoding_fingerprint());
                                    for clause in &exported {
                                        assert!(checker.check_shared_clause(clause), "unsound shared clause in cube {id}: {clause:?}");
                                        checked += 1;
                                    }
                                }
                                let mut pool = pool_ref.lock().unwrap();
                                pool.learned += learned;
                                pool.independent += independent;
                                pool.checked += checked;
                                if share_pool { pool.publish(worker, &fresh, exported); }
                            }
                            r
                        };
                        completed += 1;
                        let spent = t.elapsed().as_secs_f64();
                        // (per-node busy time, read by the parent-cutoff monitor)
                        busy += spent;
                        let mut g = sched_ref.lock().unwrap();
                        if stats_enabled {
                            let propagation_unsat=matches!(&result,Some(a) if a.is_empty()) && sat_counts.is_some_and(|c|c.0==0);
                            let status=if propagation_unsat {json::JsonValue::from("unsat-by-propagation")}
                                else {result.as_ref().map(|a|json::JsonValue::from(a.len())).unwrap_or_else(||json::JsonValue::from("interrupted"))};
                            let source=g.nodes[id].parent.and_then(|p|g.nodes[p].owner);
                            let parent=g.nodes[id].parent;
                            let mut row=json::object! {index:id,edges_fixed:cube.edges.len(),sat_wall_seconds:spent,
                                conflicts:sat_counts.map(|v|v.2),decisions:sat_counts.map(|v|v.0),result:status,
                                thread:worker,stolen_from:source,parent:parent};
                            if let Some(old)=g.stats.get(&id) {row["sat_wall_seconds"]=json::JsonValue::from(old["sat_wall_seconds"].as_f64().unwrap_or(0.0)+spent);}
                            g.stats.insert(id,row);
                        }
                        g.nodes[id].spent = spent;
                        g.running.retain(|&r| r != id);
                        g.nodes[id].worker = None;
                        match result {
                            Some(answers) => {
                                if options.short_only && !answers.is_empty() {
                                    stop_ref.store(true, Ordering::Relaxed);
                                }
                                if verify_cubes {
                                    let reference = enumerate_answers_numlin_with_options(
                                        clues_ref, max, &fixed, options,
                                    );
                                    assert_eq!(answers.len(), reference.len(), "cube {id}");
                                }
                                if g.nodes[id].resolved || g.ancestor_resolved(id) {
                                    // Settled by its parts (or an ancestor) first: this work is the loser.
                                    g.wasted += spent;
                                    eprintln!(
                                        "[progress] cube {id} (depth {depth}, est {:.2e}) finished after {:.1}s but was already settled, elapsed {:.0}s",
                                        cube.weight, spent, started_at.elapsed().as_secs_f64()
                                    );
                                } else {
                                    let n = answers.len();
                                    if cube.weight > 0.0 {
                                        g.rate_spent += spent;
                                        g.rate_weight += cube.weight;
                                    }
                                    g.complete(id, n);
                                    g.recount(split_found);
                                    g.solved += 1;
                                    let (done, total) = (g.solved, g.nodes.len());
                                    eprintln!(
                                        "[progress] cube {id} (depth {depth}, est {:.2e}, parent {}) done in {:.1}s ({n} sol) -> {done}/{total} cubes, elapsed {:.0}s",
                                        cube.weight, g.nodes[id].parent.map(|p| p.to_string()).unwrap_or_else(|| "-".to_string()), spent, started_at.elapsed().as_secs_f64()
                                    );
                                }
                            }
                            None => {
                                if g.nodes[id].resolved || g.ancestor_resolved(id) {
                                    // Interrupted because the parts finished first: the parts' time replaced ours.
                                    g.wasted += spent;
                                    eprintln!(
                                        "[progress] cube {id} (depth {depth}) interrupted after {:.1}s (settled by its parts), elapsed {:.0}s",
                                        spent, started_at.elapsed().as_secs_f64()
                                    );
                                } else if g.nodes[id].abandoned {
                                    // Interrupted by the overrun monitor or the parent cutoff: its parts carry on.
                                    g.wasted += spent;
                                    eprintln!(
                                        "[progress] cube {id} (depth {depth}) interrupted after {:.1}s ({}, replaced by its parts), elapsed {:.0}s",
                                        spent, if g.nodes[id].cutoff { "parent cutoff: children busier" } else { "overrun" }, started_at.elapsed().as_secs_f64()
                                    );
                                } else if budget > 0 {
                                    // Budget exhausted: split and requeue (legacy mode).
                                    g.wasted += spent;
                                    let vc = g.nodes[id].cube.clone();
                                    drop(g);
                                    let (parts, extra) = split_cube(problem_ref.clone(), &vc, resplit, cube_options_ref);
                                    let mut g = sched_ref.lock().unwrap();
                                    g.splits += 1;
                                    let n_parts = parts.len();
                                    if n_parts == 0 {
                                        g.complete(id, extra);
                                        g.recount(split_found);
                                    } else {
                                        g.nodes[id].remaining = n_parts;
                                        let mut ids = Vec::new();
                                        for part in parts {
                                            let nid = g.nodes.len();
                                            g.nodes.push(Node { cube: part, parent: Some(id), depth: depth + 1, remaining: 0, resolved: false, split: false, abandoned: false, cutoff: false, spent: 0.0, answers: 0, owner: None, worker: None, started: None });
                                            ids.push(nid);
                                        }
                                        for &nid in ids.iter().rev() {
                                            g.queue.push_front(nid);
                                        }
                                        if extra > 0 {
                                            g.nodes[id].answers = extra; // added when the parts settle it
                                        }
                                    }
                                    eprintln!(
                                        "[resplit] cube {id} (depth {depth}) hit {budget} conflicts after {:.1}s -> {n_parts} parts, queue {}, elapsed {:.0}s",
                                        spent, g.queue.len(), started_at.elapsed().as_secs_f64()
                                    );
                                } else {
                                    // Spurious interrupt (meant for an earlier node): run it again.
                                    g.queue.push_front(id);
                                }
                            }
                        }
                    }
                    if let Some(solver) = &mut incremental {
                        if share_every > 0 {
                            let t = Instant::now();
                            pool_ref
                                .lock()
                                .unwrap()
                                .exchange(worker, solver, &mut cursor);
                            busy += t.elapsed().as_secs_f64();
                        }
                    }
                    sched_ref.lock().unwrap().handles[worker] = None;
                    busy
                })
            })
            .collect();
        handles.into_iter().map(|h| h.join().unwrap()).collect()
    });
    let total_busy: f64 = per_thread.iter().sum();
    let g = sched.into_inner().unwrap();
    let mut n = g.found;
    if exact_count && n < max && !options.full_cover {
        // The row-scan split keeps row-scan canonical forms only (U-turn ban plus the L-shape
        // tie-break), so the cube count can be below the SAT count by L-shape variants.
        // Existence is unaffected (every solution has a canonical equivalent with unused
        // cells preserved), so this unrestricted re-enumeration is opt-in: it costs a full
        // single-solver run (g34: about 1.5 h).
        println!("cube count {n} < {max}: running the unrestricted enumeration (--exact-count)");
        n = enumerate_answers_numlin_with_options(&clues, max, &[], options).len();
    }
    if options.short_only {
        println!("short-circuit: {}", if n > 0 { "yes" } else { "no" });
    } else {
        println!("solutions (up to {max}): {}", n.min(max));
    }
    println!("shared clauses: {}", pool.lock().unwrap().clauses.len());
    if fixed_units {
        let pool = pool.lock().unwrap();
        println!(
            "dependency learnts: {} independent / {} total ({:.3}%), checked: {}",
            pool.independent,
            pool.learned,
            100.0 * pool.independent as f64 / pool.learned.max(1) as f64,
            pool.checked
        );
        println!(
            "pool candidates: {}, imported clauses: {}",
            pool.eligible, pool.imported
        );
    }
    println!(
        "cubes solved: {} (steals: {}, parent cutoffs: {}, overrun splits: {}, budget re-splits: {}, total nodes: {}, discarded cpu: {:.3}s)",
        g.solved, g.steals, g.cutoffs, g.overruns, g.splits, g.nodes.len(), g.wasted
    );
    println!("total cpu (sum of cube times): {:.3}s", total_busy);
    if let Some(path) = cube_stats {
        use std::io::Write;
        let mut writer =
            std::io::BufWriter::new(std::fs::File::create(path).expect("create cube stats"));
        let mut times = Vec::new();
        let mut propagation_unsat = 0;
        for (id, node) in g.nodes.iter().enumerate() {
            if let Some(row) = g.stats.get(&id) {
                times.push(row["sat_wall_seconds"].as_f64().unwrap());
                propagation_unsat +=
                    usize::from(row["result"].as_str() == Some("unsat-by-propagation"));
                writeln!(writer, "{}", row.dump()).unwrap();
            } else {
                let row = json::object! {index:id,edges_fixed:node.cube.edges.len(),sat_wall_seconds:0.0,
                conflicts:json::Null,result:if node.resolved {"split-solution"} else {"not-run"},thread:json::Null,stolen_from:json::Null,parent:node.parent};
                writeln!(writer, "{}", row.dump()).unwrap();
            }
        }
        writer.flush().unwrap();
        times.sort_by(f64::total_cmp);
        let count = times.len();
        let sum: f64 = times.iter().sum();
        let median = if count == 0 {
            0.0
        } else if count % 2 == 0 {
            (times[count / 2 - 1] + times[count / 2]) / 2.0
        } else {
            times[count / 2]
        };
        println!("cube stats: count {} solved {} cpu {:.6} s wall {:.6} s max {:.6} s mean {:.6} s median {:.6} s propagation-unsat {}",
            g.nodes.len(),count,sum,started.elapsed().as_secs_f64(),times.last().copied().unwrap_or(0.0),sum/count.max(1) as f64,median,propagation_unsat);
    }
    println!("elapsed: {:.3?}", started.elapsed());
    println!("threads: {threads}");
    std::process::exit(if n > 0 { 0 } else { 1 });
}

#[cfg(test)]
mod cube_file_tests {
    use super::*;
    #[test]
    fn validate_cube_file() {
        let dir = std::env::temp_dir().join(format!("numlin-cube-file-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("cubes.json");
        let path = path.to_str().unwrap();
        let sample = r#"{"width":15,"height":15,"direction":0,"cubes":[{"edges":[[0,1,true]],"next":0,"weight":0.0},{"edges":[[0,1,false],[1,0,true]],"next":0,"weight":0.0},{"edges":[[0,1,false],[1,0,false]],"next":0,"weight":0.0}],"solutions_while_splitting":0,"steps":0,"elapsed_ms":0.0}"#;
        std::fs::write(path, sample).unwrap();
        let (cubes, n) = read_cubes(path, 15, 15, 0).unwrap();
        assert_eq!((cubes.len(), n), (3, 0));
        assert!(read_cubes(path, 14, 15, 0).is_err());
        assert!(read_cubes(path, 15, 14, 0).is_err());
        assert!(read_cubes(path, 15, 15, 1).is_err());
        write_cubes(path, &cubes, 15, 15, 0, 7, 1.25);
        let (again, n) = read_cubes(path, 15, 15, 0).unwrap();
        assert_eq!(again.len(), 3);
        assert_eq!(n, 7);
        assert_eq!(again[1].edges, cubes[1].edges);
        for bad in [
            sample.replace("[0,1,true]", "[0,0,true]"),
            sample.replace("[0,1,true]", "[29,1,true]"),
            sample.replace("\"next\":0", "\"next\":1"),
            sample.replace("\"weight\":0.0", "\"weight\":-1"),
            sample.replace("[0,1,true]", "[0,1,1]"),
            sample.replace("\"cubes\":[", "\"cubes\":null,\"other\":["),
        ] {
            std::fs::write(path, bad).unwrap();
            assert!(read_cubes(path, 15, 15, 0).is_err());
        }
        std::fs::remove_dir_all(dir).unwrap();
    }
}
